-- ── hand-written: a bank account's details ──────────────────────────────────────────────────────
-- Runs as whoever writes the row (not SECURITY DEFINER): only a bank account of the chart, and who
-- wrote it when are the database's own answers.
CREATE FUNCTION app.check_cash_bank_account() RETURNS trigger
  LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  IF current_user <> 'app_runtime' THEN
    RETURN NEW;
  END IF;
  IF NEW.tenant_id IS DISTINCT FROM app.tenant_id() THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF TG_OP = 'INSERT' THEN
    NEW.created_at := now();
    NEW.created_by := app.current_user_id();
  ELSIF NEW.account_id <> OLD.account_id THEN
    RAISE EXCEPTION 'the details stay with their account' USING ERRCODE = 'SE330';
  END IF;
  NEW.updated_at := clock_timestamp();
  NEW.updated_by := app.current_user_id();
  -- Held until the transaction ends, so the account is not removed (and another put in under its
  -- id) meanwhile: a removal that comes first is waited for, and then the details are refused.
  PERFORM 1 FROM public.accounts a WHERE a.tenant_id = NEW.tenant_id AND a.id = NEW.account_id AND a.control_type = 'bank' AND NOT a.is_group FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'bank details belong to a bank account' USING ERRCODE = 'SE330';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_cash_bank_account() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER cash_bank_accounts_check BEFORE INSERT OR UPDATE ON public.cash_bank_accounts FOR EACH ROW EXECUTE FUNCTION app.check_cash_bank_account();
--> statement-breakpoint

-- ── hand-written: a cash or bank account is archived only when it holds nothing ─────────────────
-- Everything ever posted to it adds up to nil, whatever its date, and no cheque deposited in it is
-- still waiting to clear (clearing would post to it). A trigger of track C's own on the chart.
CREATE FUNCTION app.check_cash_bank_archive() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_balance numeric;
BEGIN
  -- Migrations and maintenance, run as postgres, are not anyone's archiving (a test archives an
  -- account that way); the app's role cannot become postgres.
  IF session_user = 'postgres' THEN
    RETURN NEW;
  END IF;
  IF OLD.archived_at IS NOT NULL OR NEW.archived_at IS NULL OR NEW.is_group OR NEW.control_type IS NULL OR NEW.control_type NOT IN ('cash', 'bank') THEN
    RETURN NEW;
  END IF;
  SELECT coalesce(sum(l.debit - l.credit), 0) INTO v_balance FROM public.journal_lines l WHERE l.tenant_id = NEW.tenant_id AND l.account_id = NEW.id;
  IF v_balance <> 0 THEN
    RAISE EXCEPTION 'a cash or bank account is archived only when it holds nothing; % holds %', NEW.name, v_balance USING ERRCODE = 'SE340';
  END IF;
  IF EXISTS (SELECT 1 FROM public.receipts r WHERE r.tenant_id = NEW.tenant_id AND r.account_id = NEW.id AND r.cheque_status = 'deposited') THEN
    RAISE EXCEPTION 'a cheque deposited in % is still waiting to clear', NEW.name USING ERRCODE = 'SE340';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_cash_bank_archive() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER accounts_cash_bank_archive BEFORE UPDATE ON public.accounts FOR EACH ROW EXECUTE FUNCTION app.check_cash_bank_archive();
--> statement-breakpoint
ALTER TABLE public.accounts ENABLE ALWAYS TRIGGER accounts_cash_bank_archive;
--> statement-breakpoint

-- ── hand-written: what transfers and expenses post ──────────────────────────────────────────────
-- Not for the app to call. One of the company's cash or bank accounts that takes postings: not a
-- heading, not archived. Anything else is refused (SE331). The account is held until the
-- transaction ends, so it cannot be archived while something is being posted to it.
CREATE FUNCTION app.cash_bank_account(p_tenant uuid, p_account uuid) RETURNS public.accounts
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_account public.accounts%ROWTYPE;
BEGIN
  SELECT a.* INTO v_account FROM public.accounts a WHERE a.tenant_id = p_tenant AND a.id = p_account FOR SHARE;
  IF NOT FOUND OR v_account.is_group OR v_account.archived_at IS NOT NULL OR v_account.control_type IS NULL OR v_account.control_type NOT IN ('cash', 'bank') THEN
    RAISE EXCEPTION 'choose one of the company''s cash or bank accounts that is in use' USING ERRCODE = 'SE331';
  END IF;
  RETURN v_account;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.cash_bank_account(uuid, uuid) FROM PUBLIC;
--> statement-breakpoint
-- Not for the app to call. Before a cancellation posts to an account, the account is in use and
-- held: an archived account is restored first, so it never holds money while archived.
CREATE FUNCTION app.cash_bank_reopenable(p_tenant uuid, p_account uuid) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_archived timestamptz;
BEGIN
  -- Held and read in one statement: an archiving that comes first is seen, one that comes after waits.
  SELECT a.archived_at INTO v_archived FROM public.accounts a WHERE a.tenant_id = p_tenant AND a.id = p_account FOR SHARE;
  IF v_archived IS NOT NULL THEN
    RAISE EXCEPTION 'the account is archived; restore it first' USING ERRCODE = 'SE341';
  END IF;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.cash_bank_reopenable(uuid, uuid) FROM PUBLIC;
--> statement-breakpoint
-- Not for the app to call. A journal taken back on a day: every line the other way round.
CREATE FUNCTION app.cash_bank_reverse(p_journal uuid, p_date date, p_memo text) RETURNS uuid
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_original public.journals%ROWTYPE;
  v_reversal uuid;
  v_lines integer;
  v_total numeric;
BEGIN
  SELECT j.* INTO v_original FROM public.journals j WHERE j.tenant_id = app.tenant_id() AND j.id = p_journal;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such journal to reverse' USING ERRCODE = 'SE334';
  END IF;
  SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
  INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, reverses_journal_id, document_number, memo, branch_id, created_by)
    VALUES (v_original.tenant_id, p_date, 'reversal', v_original.id, v_original.id, NULL, left(p_memo, 500), v_original.branch_id, app.current_user_id())
    RETURNING id INTO v_reversal;
  INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description, customer_id, supplier_id)
    SELECT l.tenant_id, v_reversal, l.line_no, l.account_id, l.credit, l.debit, l.description, l.customer_id, l.supplier_id
    FROM public.journal_lines l WHERE l.tenant_id = v_original.tenant_id AND l.journal_id = v_original.id;
  SELECT count(*), sum(l.debit) INTO v_lines, v_total FROM public.journal_lines l WHERE l.tenant_id = v_original.tenant_id AND l.journal_id = v_reversal;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_original.tenant_id, app.current_user_id(), app.tenant_role(), 'journal.reverse', 'journal', v_reversal,
      jsonb_build_object('date', p_date, 'reverses', v_original.id, 'source', v_original.source_type, 'reversesNumber', v_original.document_number, 'lines', v_lines, 'total', v_total::text));
  RETURN v_reversal;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.cash_bank_reverse(uuid, date, text) FROM PUBLIC;
--> statement-breakpoint
-- Who may move and spend the company's money, on what day.
CREATE FUNCTION app.cash_bank_may_write(p_date date) RETURNS void
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  IF app.tenant_id() IS NULL OR app.current_user_id() IS NULL OR app.tenant_role() IS NULL OR app.tenant_role() NOT IN ('owner', 'accountant') THEN
    RAISE EXCEPTION 'this role does not move or spend the company''s money' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'money is moved in read committed transactions' USING ERRCODE = 'SE332';
  END IF;
  IF p_date IS NULL OR p_date > (now() AT TIME ZONE 'Asia/Karachi')::date THEN
    RAISE EXCEPTION 'that date has not come yet' USING ERRCODE = 'SE333';
  END IF;
  PERFORM app.require_open_period(app.tenant_id(), p_date);
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.cash_bank_may_write(date) FROM PUBLIC;
--> statement-breakpoint

-- Money moved from one of the company's cash or bank accounts to another. Only someone who works
-- in every branch moves it: the accounts belong to the whole company.
CREATE FUNCTION app.record_cash_transfer(p_key uuid, p_from uuid, p_to uuid, p_date date, p_amount numeric, p_reference text, p_memo text) RETURNS text
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_user uuid := app.current_user_id();
  v_from public.accounts%ROWTYPE;
  v_to public.accounts%ROWTYPE;
  v_id uuid := coalesce(p_key, gen_random_uuid());
  v_number text;
  v_journal uuid;
  v_sent public.cash_transfers%ROWTYPE;
BEGIN
  PERFORM app.cash_bank_may_write(p_date);
  IF app.tenant_branch_ids() IS NOT NULL THEN
    RAISE EXCEPTION 'money is moved between the company''s accounts by someone who works in every branch' USING ERRCODE = 'insufficient_privilege';
  END IF;
  -- Sent again with the same key: the first is the one recorded, if it is the same transfer.
  PERFORM pg_advisory_xact_lock(hashtextextended('cash-transfer:' || v_id::text, 0));
  SELECT t.* INTO v_sent FROM public.cash_transfers t WHERE t.tenant_id = v_tenant AND t.id = v_id;
  IF FOUND THEN
    IF v_sent.from_account_id IS DISTINCT FROM p_from OR v_sent.to_account_id IS DISTINCT FROM p_to OR v_sent.transfer_date IS DISTINCT FROM p_date OR v_sent.amount IS DISTINCT FROM p_amount THEN
      RAISE EXCEPTION 'already recorded as % with other figures', v_sent.number USING ERRCODE = 'SE342';
    END IF;
    RETURN v_sent.number;
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 OR p_amount >= 1e14 OR round(p_amount, 2) <> p_amount THEN
    RAISE EXCEPTION 'an amount in rupees and paisa, above nothing' USING ERRCODE = 'SE332';
  END IF;
  IF p_from IS NULL OR p_to IS NULL OR p_from = p_to THEN
    RAISE EXCEPTION 'money is moved between two different accounts' USING ERRCODE = 'SE331';
  END IF;
  v_from := app.cash_bank_account(v_tenant, p_from);
  v_to := app.cash_bank_account(v_tenant, p_to);
  v_number := app.next_document_number('TR', p_date);
  SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
  INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, created_by)
    VALUES (v_tenant, p_date, 'cash_transfer', v_id, v_number, left('Moved from ' || v_from.name || ' to ' || v_to.name, 500), v_user)
    RETURNING id INTO v_journal;
  INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
    VALUES (v_tenant, v_journal, 1, v_to.id, p_amount, 0, 'From ' || v_from.name),
           (v_tenant, v_journal, 2, v_from.id, 0, p_amount, 'To ' || v_to.name);
  INSERT INTO public.cash_transfers (id, tenant_id, number, transfer_date, from_account_id, to_account_id, amount, reference, memo, status, journal_id, created_by)
    VALUES (v_id, v_tenant, v_number, p_date, v_from.id, v_to.id, p_amount, nullif(btrim(p_reference), ''), nullif(btrim(p_memo), ''), 'posted', v_journal, v_user);
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, app.tenant_role(), 'journal.post', 'journal', v_journal,
      jsonb_build_object('date', p_date, 'source', 'cash_transfer', 'sourceId', v_id, 'number', v_number, 'lines', 2, 'total', p_amount::text)),
           (v_tenant, v_user, app.tenant_role(), 'cash_transfer.record', 'cash_transfer', v_id,
      jsonb_build_object('number', v_number, 'date', p_date, 'from', v_from.name, 'to', v_to.name, 'amount', p_amount::text));
  RETURN v_number;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.record_cash_transfer(uuid, uuid, uuid, date, numeric, text, text) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.record_cash_transfer(uuid, uuid, uuid, date, numeric, text, text) TO app_runtime;
--> statement-breakpoint
-- A transfer entered by mistake is taken back with a reversal, on or after its own day.
CREATE FUNCTION app.cancel_cash_transfer(p_id uuid, p_date date, p_reason text) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_doc public.cash_transfers%ROWTYPE;
  v_reversal uuid;
BEGIN
  PERFORM app.cash_bank_may_write(p_date);
  IF app.tenant_branch_ids() IS NOT NULL THEN
    RAISE EXCEPTION 'money is moved between the company''s accounts by someone who works in every branch' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT t.* INTO v_doc FROM public.cash_transfers t WHERE t.tenant_id = v_tenant AND t.id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such transfer in this company' USING ERRCODE = 'SE334';
  END IF;
  IF v_doc.status <> 'posted' THEN
    RAISE EXCEPTION 'this transfer has already been cancelled' USING ERRCODE = 'SE335';
  END IF;
  IF p_date < v_doc.transfer_date THEN
    RAISE EXCEPTION 'a transfer is cancelled on or after its own day' USING ERRCODE = 'SE333';
  END IF;
  IF p_reason IS NULL OR char_length(btrim(p_reason)) NOT BETWEEN 3 AND 300 THEN
    RAISE EXCEPTION 'say why the transfer is cancelled' USING ERRCODE = 'SE332';
  END IF;
  PERFORM app.cash_bank_reopenable(v_tenant, v_doc.from_account_id);
  PERFORM app.cash_bank_reopenable(v_tenant, v_doc.to_account_id);
  v_reversal := app.cash_bank_reverse(v_doc.journal_id, p_date, 'Cancelled: ' || v_doc.number || ' (' || btrim(p_reason) || ')');
  UPDATE public.cash_transfers t SET status = 'cancelled', reversal_journal_id = v_reversal, cancelled_at = now(), cancelled_by = app.current_user_id(), cancel_reason = btrim(p_reason)
    WHERE t.tenant_id = v_tenant AND t.id = v_doc.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, before, after)
    VALUES (v_tenant, app.current_user_id(), app.tenant_role(), 'cash_transfer.cancel', 'cash_transfer', v_doc.id,
      jsonb_build_object('status', 'posted'), jsonb_build_object('status', 'cancelled', 'number', v_doc.number, 'date', p_date, 'reason', btrim(p_reason)));
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.cancel_cash_transfer(uuid, date, text) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.cancel_cash_transfer(uuid, date, text) TO app_runtime;
--> statement-breakpoint

-- Money spent out of a cash or bank account, in one act: the lines, the province's tax on
-- services added to them in proportion and withheld whole, income tax withheld at the supplier's
-- rate, each from its dated line of the withholding tables (Step 25's), and the journal. Tax is
-- withheld only by a company that withholds (Purchases, settings) and only from a supplier on the
-- list. `p_lines` is a list of {account, description, amount}.
CREATE FUNCTION app.record_expense(p_key uuid, p_date date, p_account uuid, p_supplier uuid, p_payee text, p_branch uuid, p_reference text, p_memo text, p_lines jsonb,
                                   p_income_tax_code text, p_provincial_tax_code text) RETURNS text
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_user uuid := app.current_user_id();
  v_scope uuid[] := app.tenant_branch_ids();
  v_paid_from public.accounts%ROWTYPE;
  v_supplier public.suppliers%ROWTYPE;
  v_id uuid := coalesce(p_key, gen_random_uuid());
  v_line jsonb;
  v_ord bigint;
  v_shares jsonb := '{}'::jsonb;
  v_sent public.expenses%ROWTYPE;
  v_target public.accounts%ROWTYPE;
  v_count integer := 0;
  v_amount numeric := 0;
  v_provincial numeric := 0;
  v_provincial_rule public.withholding_rules%ROWTYPE;
  v_rule public.withholding_rules%ROWTYPE;
  v_rate numeric;
  v_base numeric;
  v_total numeric;
  v_withheld numeric := 0;
  v_on_list boolean := false;
  v_entries jsonb := '[]'::jsonb;
  v_entry jsonb;
  v_number text;
  v_journal uuid;
  v_no integer := 0;
  v_seen integer := 0;
  v_share numeric;
  v_shared numeric := 0;
  v_name text;
BEGIN
  PERFORM app.cash_bank_may_write(p_date);
  IF v_scope IS NOT NULL AND (p_branch IS NULL OR NOT (p_branch = ANY (v_scope))) THEN
    RAISE EXCEPTION 'choose one of your branches' USING ERRCODE = 'SE336';
  END IF;
  IF p_branch IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.branches b WHERE b.tenant_id = v_tenant AND b.id = p_branch) THEN
    RAISE EXCEPTION 'choose one of your branches' USING ERRCODE = 'SE336';
  END IF;
  v_paid_from := app.cash_bank_account(v_tenant, p_account);
  -- Paid to a supplier on the list, or to someone named in words; never both, never neither.
  IF (p_supplier IS NULL) = (nullif(btrim(p_payee), '') IS NULL) THEN
    RAISE EXCEPTION 'an expense is paid to a supplier on the list or to someone named' USING ERRCODE = 'SE337';
  END IF;
  IF p_supplier IS NOT NULL THEN
    SELECT s.* INTO v_supplier FROM public.suppliers s WHERE s.tenant_id = v_tenant AND s.id = p_supplier AND s.archived_at IS NULL;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'choose one of the company''s suppliers' USING ERRCODE = 'SE337';
    END IF;
    v_on_list := v_supplier.atl_status = 'active';
    v_name := v_supplier.name;
  ELSE
    IF char_length(btrim(p_payee)) NOT BETWEEN 2 AND 120 THEN
      RAISE EXCEPTION 'name who was paid' USING ERRCODE = 'SE337';
    END IF;
    v_name := btrim(p_payee);
  END IF;
  IF (p_income_tax_code IS NOT NULL OR p_provincial_tax_code IS NOT NULL) THEN
    IF p_supplier IS NULL THEN
      RAISE EXCEPTION 'tax is withheld from a supplier on the list' USING ERRCODE = 'SE338';
    END IF;
    IF NOT coalesce((SELECT p.withholding_on FROM public.purchase_settings p WHERE p.tenant_id = v_tenant), false) THEN
      RAISE EXCEPTION 'this company does not withhold tax from its suppliers' USING ERRCODE = 'SE338';
    END IF;
  END IF;

  -- The lines: an expense or asset account of the chart that takes postings and is no one's
  -- control (Bank charges, which is locked, may be spent on too); a description; an amount.
  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' OR jsonb_array_length(p_lines) NOT BETWEEN 1 AND 50 THEN
    RAISE EXCEPTION 'an expense has from 1 to 50 lines' USING ERRCODE = 'SE339';
  END IF;
  FOR v_line IN SELECT e.value FROM jsonb_array_elements(p_lines) AS e(value)
  LOOP
    v_count := v_count + 1;
    SELECT a.* INTO v_target FROM public.accounts a WHERE a.tenant_id = v_tenant AND a.id = (v_line->>'account')::uuid;
    IF NOT FOUND OR v_target.is_group OR v_target.archived_at IS NOT NULL OR v_target.type NOT IN ('expense', 'asset')
       OR (v_target.control_type IS NOT NULL AND v_target.control_type <> 'bank_charges') THEN
      RAISE EXCEPTION 'line %: choose an expense or asset account that takes postings', v_count USING ERRCODE = 'SE339';
    END IF;
    IF char_length(btrim(coalesce(v_line->>'description', ''))) NOT BETWEEN 2 AND 200 THEN
      RAISE EXCEPTION 'line %: say what it was for', v_count USING ERRCODE = 'SE339';
    END IF;
    IF (v_line->>'amount')::numeric IS NULL OR (v_line->>'amount')::numeric <= 0 OR (v_line->>'amount')::numeric >= 1e14
       OR round((v_line->>'amount')::numeric, 2) <> (v_line->>'amount')::numeric THEN
      RAISE EXCEPTION 'line %: an amount in rupees and paisa, above nothing', v_count USING ERRCODE = 'SE339';
    END IF;
    v_amount := v_amount + (v_line->>'amount')::numeric;
  END LOOP;

  -- The province's tax on the services, at its rate on the day, withheld whole.
  IF p_provincial_tax_code IS NOT NULL THEN
    v_provincial_rule := app.withholding_rule_on(v_tenant, 'provincial_sales_tax', p_provincial_tax_code, p_date);
    v_provincial := round(v_amount * v_provincial_rule.rate / 100, 2);
    v_entries := v_entries || jsonb_build_object('kind', 'provincial_sales_tax', 'control', 'wht_provincial_tax', 'rule', v_provincial_rule.id,
      'code', v_provincial_rule.code, 'law', v_provincial_rule.legal_reference, 'base', v_amount, 'rate', v_provincial_rule.rate, 'amount', v_provincial);
  END IF;
  v_total := v_amount + v_provincial;
  IF v_provincial > 0 THEN
    WITH l AS (
      SELECT e.ord, v_provincial * (e.value->>'amount')::numeric * 100 / v_amount AS exact
      FROM jsonb_array_elements(p_lines) WITH ORDINALITY AS e(value, ord)
    ), f AS (
      SELECT l.ord, floor(l.exact) AS cents, l.exact - floor(l.exact) AS cut FROM l
    ), r AS (
      SELECT f.ord, f.cents, row_number() OVER (ORDER BY f.cut DESC, f.ord) AS rank,
             round(v_provincial * 100) - sum(f.cents) OVER () AS spare
      FROM f
    )
    SELECT jsonb_object_agg(r.ord::text, (r.cents + CASE WHEN r.rank <= r.spare THEN 1 ELSE 0 END) / 100.0) INTO v_shares FROM r;
  END IF;
  -- Income tax at the supplier's rate: whether it is on the Active Taxpayers List as recorded today.
  IF p_income_tax_code IS NOT NULL THEN
    v_rule := app.withholding_rule_on(v_tenant, 'income_tax', p_income_tax_code, p_date);
    v_rate := CASE WHEN v_on_list THEN v_rule.rate ELSE coalesce(v_rule.rate_non_atl, v_rule.rate) END;
    v_base := CASE v_rule.base::text WHEN 'gross_amount' THEN v_total WHEN 'taxable_value' THEN v_amount ELSE NULL END;
    IF v_base IS NULL OR v_base <= 0 OR v_rate <= 0 THEN
      RAISE EXCEPTION 'that income tax line is not one an expense is withheld under' USING ERRCODE = 'SE339';
    END IF;
    v_entries := v_entries || jsonb_build_object('kind', 'income_tax', 'control', 'wht_income_tax', 'rule', v_rule.id, 'code', v_rule.code,
      'law', v_rule.legal_reference, 'base', v_base, 'rate', v_rate, 'amount', round(v_base * v_rate / 100, 2));
  END IF;
  SELECT coalesce(sum((e.value->>'amount')::numeric), 0) INTO v_withheld FROM jsonb_array_elements(v_entries) AS e(value);
  IF v_withheld > v_total OR EXISTS (SELECT 1 FROM jsonb_array_elements(v_entries) AS e(value) WHERE (e.value->>'amount')::numeric <= 0) THEN
    RAISE EXCEPTION 'what would be withheld is not an amount between nothing and the expense' USING ERRCODE = 'SE339';
  END IF;

  -- Sent again with the same key, after every check above: the first is the one recorded, if it is the same expense.
  PERFORM pg_advisory_xact_lock(hashtextextended('expense:' || v_id::text, 0));
  SELECT e.* INTO v_sent FROM public.expenses e WHERE e.tenant_id = v_tenant AND e.id = v_id;
  IF FOUND THEN
    IF v_sent.expense_date IS DISTINCT FROM p_date OR v_sent.account_id IS DISTINCT FROM p_account OR v_sent.supplier_id IS DISTINCT FROM p_supplier
       OR v_sent.payee IS DISTINCT FROM (CASE WHEN p_supplier IS NULL THEN btrim(p_payee) END) OR v_sent.amount IS DISTINCT FROM v_amount OR v_sent.total IS DISTINCT FROM v_total THEN
      RAISE EXCEPTION 'already recorded as % with other figures', v_sent.number USING ERRCODE = 'SE342';
    END IF;
    RETURN v_sent.number;
  END IF;
  v_number := app.next_document_number('EX', p_date);
  SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
  INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, branch_id, created_by)
    VALUES (v_tenant, p_date, 'expense', v_id, v_number, left('Paid to ' || v_name, 500), p_branch, v_user)
    RETURNING id INTO v_journal;
  INSERT INTO public.expenses (id, tenant_id, number, expense_date, account_id, supplier_id, payee, branch_id, reference, memo, amount, provincial_tax, total, withheld, paid, status, journal_id, created_by)
    VALUES (v_id, v_tenant, v_number, p_date, v_paid_from.id, p_supplier, CASE WHEN p_supplier IS NULL THEN btrim(p_payee) END, p_branch,
            nullif(btrim(p_reference), ''), nullif(btrim(p_memo), ''), v_amount, v_provincial, v_total, v_withheld, v_total - v_withheld, 'posted', v_journal, v_user);
  -- Each line with its share of the province's tax, worked out above.
  FOR v_line, v_ord IN SELECT e.value, e.ord FROM jsonb_array_elements(p_lines) WITH ORDINALITY AS e(value, ord)
  LOOP
    v_seen := v_seen + 1;
    v_share := coalesce((v_shares->>v_ord::text)::numeric, 0);
    v_shared := v_shared + v_share;
    INSERT INTO public.expense_lines (tenant_id, expense_id, line_no, account_id, description, amount, provincial_share)
      VALUES (v_tenant, v_id, v_seen, (v_line->>'account')::uuid, btrim(v_line->>'description'), (v_line->>'amount')::numeric, v_share);
    v_no := v_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, v_no, (v_line->>'account')::uuid, (v_line->>'amount')::numeric + v_share, 0, left(btrim(v_line->>'description'), 300));
  END LOOP;
  FOR v_entry IN SELECT e.value FROM jsonb_array_elements(v_entries) AS e(value)
  LOOP
    v_no := v_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, v_no, app.control_account(v_tenant, v_entry->>'control'), 0, (v_entry->>'amount')::numeric,
              'Withheld from ' || v_name || ' at ' || trim_scale((v_entry->>'rate')::numeric)::text || '%');
    INSERT INTO public.expense_withholdings (tenant_id, expense_id, supplier_id, entry_date, kind, rule_id, code, legal_reference, on_active_list, base_amount, rate, amount, journal_id, created_by)
      VALUES (v_tenant, v_id, p_supplier, p_date, v_entry->>'kind', (v_entry->>'rule')::uuid, v_entry->>'code', v_entry->>'law', v_on_list,
              (v_entry->>'base')::numeric, (v_entry->>'rate')::numeric, (v_entry->>'amount')::numeric, v_journal, v_user);
  END LOOP;
  IF v_total - v_withheld > 0 THEN
    v_no := v_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, v_no, v_paid_from.id, 0, v_total - v_withheld, 'Paid to ' || v_name);
  END IF;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, app.tenant_role(), 'journal.post', 'journal', v_journal,
      jsonb_build_object('date', p_date, 'source', 'expense', 'sourceId', v_id, 'number', v_number, 'lines', v_no, 'total', v_total::text)),
           (v_tenant, v_user, app.tenant_role(), 'expense.record', 'expense', v_id,
      jsonb_build_object('number', v_number, 'date', p_date, 'paidTo', v_name, 'from', v_paid_from.name, 'total', v_total::text, 'withheld', v_withheld::text, 'paid', (v_total - v_withheld)::text));
  RETURN v_number;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.record_expense(uuid, date, uuid, uuid, text, uuid, text, text, jsonb, text, text) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.record_expense(uuid, date, uuid, uuid, text, uuid, text, text, jsonb, text, text) TO app_runtime;
