-- An expense entered by mistake is taken back with a reversal, on or after its own day: the
-- expense, the tax withheld and the money all go back.
CREATE FUNCTION app.cancel_expense(p_id uuid, p_date date, p_reason text) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_scope uuid[] := app.tenant_branch_ids();
  v_doc public.expenses%ROWTYPE;
  v_reversal uuid;
BEGIN
  PERFORM app.cash_bank_may_write(p_date);
  SELECT e.* INTO v_doc FROM public.expenses e WHERE e.tenant_id = v_tenant AND e.id = p_id FOR UPDATE;
  IF NOT FOUND OR (v_scope IS NOT NULL AND (v_doc.branch_id IS NULL OR NOT (v_doc.branch_id = ANY (v_scope)))) THEN
    RAISE EXCEPTION 'no such expense in this company' USING ERRCODE = 'SE334';
  END IF;
  IF v_doc.status <> 'posted' THEN
    RAISE EXCEPTION 'this expense has already been cancelled' USING ERRCODE = 'SE335';
  END IF;
  IF p_date < v_doc.expense_date THEN
    RAISE EXCEPTION 'an expense is cancelled on or after its own day' USING ERRCODE = 'SE333';
  END IF;
  IF p_reason IS NULL OR char_length(btrim(p_reason)) NOT BETWEEN 3 AND 300 THEN
    RAISE EXCEPTION 'say why the expense is cancelled' USING ERRCODE = 'SE332';
  END IF;
  PERFORM app.cash_bank_reopenable(v_tenant, v_doc.account_id);
  v_reversal := app.cash_bank_reverse(v_doc.journal_id, p_date, 'Cancelled: ' || v_doc.number || ' (' || btrim(p_reason) || ')');
  UPDATE public.expenses e SET status = 'cancelled', reversal_journal_id = v_reversal, cancelled_at = now(), cancelled_by = app.current_user_id(), cancel_reason = btrim(p_reason)
    WHERE e.tenant_id = v_tenant AND e.id = v_doc.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, before, after)
    VALUES (v_tenant, app.current_user_id(), app.tenant_role(), 'expense.cancel', 'expense', v_doc.id,
      jsonb_build_object('status', 'posted'), jsonb_build_object('status', 'cancelled', 'number', v_doc.number, 'date', p_date, 'reason', btrim(p_reason)));
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.cancel_expense(uuid, date, text) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.cancel_expense(uuid, date, text) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: the shared lists (drizzle/0019_journal_documents.sql) ─────────────────────────
-- Each journal stands with its transfer or expense, and each reversal with one cancelled.
CREATE FUNCTION app.journal_backed_cash_transfer(p_journal public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.cash_transfers t
      WHERE t.tenant_id = p_journal.tenant_id AND t.id = p_journal.source_id AND t.journal_id = p_journal.id
        AND t.number = p_journal.document_number AND t.transfer_date = p_journal.journal_date)
  $$;
--> statement-breakpoint
CREATE FUNCTION app.reversal_backed_cash_transfer(p_reversal public.journals, p_original public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.cash_transfers t
      WHERE t.tenant_id = p_original.tenant_id AND t.journal_id = p_original.id AND t.reversal_journal_id = p_reversal.id AND t.status = 'cancelled')
  $$;
--> statement-breakpoint
CREATE FUNCTION app.journal_backed_expense(p_journal public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.expenses e
      WHERE e.tenant_id = p_journal.tenant_id AND e.id = p_journal.source_id AND e.journal_id = p_journal.id
        AND e.number = p_journal.document_number AND e.expense_date = p_journal.journal_date)
  $$;
--> statement-breakpoint
CREATE FUNCTION app.reversal_backed_expense(p_reversal public.journals, p_original public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.expenses e
      WHERE e.tenant_id = p_original.tenant_id AND e.journal_id = p_original.id AND e.reversal_journal_id = p_reversal.id AND e.status = 'cancelled')
  $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION
    app.journal_backed_cash_transfer(public.journals), app.reversal_backed_cash_transfer(public.journals, public.journals),
    app.journal_backed_expense(public.journals), app.reversal_backed_expense(public.journals, public.journals)
  FROM PUBLIC;
--> statement-breakpoint
-- Transfers take a number: TR-2627-00001. Expenses use the EX series the product already has.
CREATE FUNCTION app.document_type_tr() RETURNS text
  LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp
  AS $$ SELECT 'cash transfer'::text $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.document_type_tr() FROM PUBLIC;
