-- The audit rows only the functions above write: the app's role cannot write a look-alike.
-- app.audit_action_reserved asks app.audit_reserved_<the word before the full stop>.
CREATE FUNCTION app.audit_reserved_expense(p_action text) RETURNS boolean
  LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp
  AS $$ SELECT p_action IN ('expense.record', 'expense.cancel') $$;
--> statement-breakpoint
CREATE FUNCTION app.audit_reserved_cash_transfer(p_action text) RETURNS boolean
  LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp
  AS $$ SELECT p_action IN ('cash_transfer.record', 'cash_transfer.cancel') $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.audit_reserved_expense(text), app.audit_reserved_cash_transfer(text) FROM PUBLIC;
